import subprocess

def run_eva(expr, angle_unit):
    res = subprocess.run(["./executable", "-a", angle_unit, expr], capture_output=True, text=True)
    return res.stdout.strip()

for x in range(0, 360, 30):
    expr = f"sin({x})"
    d = run_eva(expr, "degree")
    g = run_eva(expr, "gradian")
