{"command":"python3 -c '
def eva_radix_hyp(val, base, fix):
    dec_str = f"{val:.{fix}f}"
    v = float(dec_str)
    int_part = int(abs(v))
    is_neg = (val < 0 or v < 0) and not (int_part == 0 and abs(v) == 0) # wait, handle negative zero
    if val < 0 and abs(v) > 0:
        is_neg = True
    else:
        is_neg = False if abs(v) == 0 else (val < 0)

    digits_map = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if int_part == 0:
        int_digits = "0"
    else:
        d = []
        n = int_part
        while n > 0:
            d.append(digits_map[n % base])
            n //= base
        int_digits = "".join(reversed(d))

    grouped = []
    for i, ch in enumerate(reversed(int_digits)):
        if i > 0 and i % 3 == 0:
            grouped.append(",")
        grouped.append(ch)
    grouped_str = "".join(reversed(grouped))
    if is_neg:
        grouped_str = "-" + grouped_str

    if len(grouped_str) < 12:
        buf = list(" " * (12 - len(grouped_str)) + grouped_str)
        for idx in (0, 4, 8):
            if buf[idx] == " ":
                buf[idx] = ","
        int_formatted = "".join(buf)
    else:
        int_formatted = grouped_str

    frac_part = abs(v) - int_part
    frac_digits = []
    f = frac_part
    for _ in range(fix):
        f *= base
        digit = int(f)
        frac_digits.append(digits_map[digit])
        f -= digit
        if abs(f) < 1e-12:
            break

    frac_str = "".join(frac_digits) if frac_digits else "0"
    return f"{int_formatted}.{frac_str}"

import subprocess
mismatches = 0
for val in [0, 1, 10, 255, 1000, 12.34, -15.5, 0.5, 0.25, 0.1, 0.3333333333]:
    for base in [2, 3, 8, 16, 36]:
        for fix in [1, 2, 5, 10]:
            cmd = ["./executable", "-b", str(base), "-f", str(fix), "--", str(val)]
            out_real = subprocess.run(cmd, capture_output=True, text=True).stdout.strip()
            out_hyp = eva_radix_hyp(val, base, fix)
            if out_real != out_hyp:
                print(f"MISMATCH: val={val} base={base} fix={fix}")
                print(f"  real: {out_real!r}")
                print(f"  hyp : {out_hyp!r}")
                mismatches += 1

print("Total mismatches:", mismatches)
'"}

