fn format_number(val: f64, base: u32, fix: usize) -> String {
    if base == 10 {
        let dec_str = format!("{:.1$}", val, fix);
        let parts: Vec<&str> = dec_str.split('.').collect();
        let int_str = parts[0];
        let frac_str = if parts.len() > 1 { parts[1] } else { "" };

        let is_neg = int_str.starts_with('-');
        let digits_only = if is_neg { &int_str[1..] } else { int_str };

        let mut grouped = String::new();
        let len = digits_only.len();
        for (i, ch) in digits_only.chars().enumerate() {
            if i > 0 && (len - i) % 3 == 0 {
                grouped.push(',');
            }
            grouped.push(ch);
        }

        let prefix = if is_neg { "-" } else { "" };
        if fix > 0 {
            format!("{}{}.{}", prefix, grouped, frac_str)
        } else {
            format!("{}{}", prefix, grouped)
        }
    } else {
        let dec_str = format!("{:.1$}", val, fix);
        let v: f64 = dec_str.parse().unwrap_or(val);
        let int_part = v.abs().trunc() as u64;

        let digits_map: &[u8] = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        let mut int_digits = String::new();
        if int_part == 0 {
            int_digits.push('0');
        } else {
            let mut n = int_part;
            let mut d_vec = Vec::new();
            while n > 0 {
                d_vec.push(digits_map[(n % (base as u64)) as usize] as char);
                n /= base as u64;
            }
            d_vec.reverse();
            int_digits = d_vec.into_iter().collect();
        }

        let mut grouped = String::new();
        let len = int_digits.len();
        for (i, ch) in int_digits.chars().enumerate() {
            if i > 0 && (len - i) % 3 == 0 {
                grouped.push(',');
            }
            grouped.push(ch);
        }

        let is_neg = val < 0.0 && v.abs() > 0.0;
        let mut grouped_str = if is_neg {
            format!("-{}", grouped)
        } else {
            grouped
        };

        let int_formatted = if grouped_str.len() < 12 {
            let pad_len = 12 - grouped_str.len();
            let mut buf: Vec<char> = " ".repeat(pad_len).chars().chain(grouped_str.chars()).collect();
            for idx in [0, 4, 8] {
                if buf[idx] == '-' {
                    buf[idx] = ',';
                    if idx > 0 {
                        buf[idx - 1] = '-';
                    }
                } else if buf[idx] == ' ' {
                    buf[idx] = ',';
                }
            }
            buf.into_iter().collect()
        } else {
            grouped_str
        };

        let mut f = v.abs() - (int_part as f64);
        let mut frac_digits = Vec::new();
        for _ in 0..fix {
            f *= base as f64;
            let digit = f.trunc() as usize;
            let digit = digit.min((base - 1) as usize);
            frac_digits.push(digits_map[digit] as char);
            f -= digit as f64;
            if f.abs() < 1e-12 {
                break;
            }
        }

        let frac_str = if frac_digits.is_empty() {
            "0".to_string()
        } else {
            frac_digits.into_iter().collect()
        };

        format!("{}.{}", int_formatted, frac_str)
    }
}

fn main() {
    println!("{}", format_number(255.0, 16, 10));
    println!("{}", format_number(1000.0, 10, 10));
    println!("{}", format_number(-15.5, 3, 10));
}
