        ];
        if !one_arg_fns.contains(&name) {
            return Err(format!("Syntax Error: Unknown function '{}'", name));
        }

        if arg_tokens.is_empty() {
            return Err("Parser Error: To few arguments for function, need 1".to_string());
        }

        let v = parse_expr(arg_tokens, angle_unit, prev_ans)?;

        let to_rad = |val: f64| -> f64 {
            match angle_unit {
                AngleUnit::Degree | AngleUnit::Gradian => val.to_radians(),
                AngleUnit::Radian => val,
            }
        };

        match name {
            "sin" => Ok(to_rad(v).sin()),
            "cos" => Ok(to_rad(v).cos()),
            "tan" => Ok(to_rad(v).tan()),
            "csc" => {
                let s = to_rad(v).sin();
                if s == 0.0 || s.abs() < 1e-15 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(1.0 / s)
                }
            }
            "sec" => {
                let c = to_rad(v).cos();
                if c == 0.0 || c.abs() < 1e-15 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(1.0 / c)
                }
            }
            "cot" => {
                let t = to_rad(v).tan();
                if t == 0.0 || t.abs() < 1e-15 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(1.0 / t)
                }
            }
            "sinh" => Ok(v.sinh()),
            "cosh" => Ok(v.cosh()),
            "tanh" => Ok(v.tanh()),
            "asin" => {
                if v < -1.0 || v > 1.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(v.asin())
                }
            }
            "acos" => {
                if v < -1.0 || v > 1.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(v.acos())
                }
            }
            "atan" => Ok(v.atan()),
            "acsc" => {
                if v == 0.0 || (1.0 / v).abs() > 1.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok((1.0 / v).asin())
                }
            }
            "asec" => {
                if v == 0.0 || (1.0 / v).abs() > 1.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok((1.0 / v).acos())
                }
            }
            "acot" => {
                if v == 0.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok((1.0 / v).atan())
                }
            }
            "ln" => {
                if v <= 0.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(v.ln())
                }
            }
            "log2" => {
                if v <= 0.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(v.log2())
                }
            }
            "log10" => {
                if v <= 0.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(v.log10())
                }
            }
            "sqrt" => {
                if v < 0.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(v.sqrt())
                }
            }
            "ceil" => Ok(v.ceil()),
            "floor" => Ok(v.floor()),
            "abs" => Ok(v.abs()),
            _ => Err(format!("Syntax Error: Unknown function '{}'", name)),
        }
    }
}

fn eval(expr: &str, angle_unit: AngleUnit, prev_ans: Option<f64>) -> Result<f64, String> {
    let tokens = tokenize(expr)?;
    eval_tokens(&tokens, angle_unit, prev_ans)
}

fn main() {
