                    process::exit(2);
                }
                Err(_) => {
                    eprintln!("error: invalid value '{}' for '--base <RADIX>': invalid digit found in string\n\nFor more information, try '--help'.", val_str);
                    process::exit(2);
                }
            }
        }

        if arg.starts_with("--base=") {
            let val_str = &arg["--base=".len()..];
