            let val_str = &args[i + 1];
            match val_str.as_str() {
                "degree" => angle_unit = AngleUnit::Degree,
                "radian" => angle_unit = AngleUnit::Radian,
                "gradian" => angle_unit = AngleUnit::Gradian,
                _ => {
                    eprintln!("error: invalid value '{}' for '--angle_unit <angle_unit>'\n  [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.", val_str);
                    process::exit(2);
                }
            }
            i += 2;
            continue;
        }

        if arg.starts_with("--angle_unit=") {
            let val_str = &arg["--angle_unit=".len()..];
            match val_str {
                "degree" => angle_unit = AngleUnit::Degree,
                "radian" => angle_unit = AngleUnit::Radian,
                "gradian" => angle_unit = AngleUnit::Gradian,
                _ => {
                    eprintln!("error: invalid value '{}' for '--angle_unit <angle_unit>'\n  [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.", val_str);
                    process::exit(2);
                }
            }
            i += 1;
            continue;
        }

        if arg.starts_with('-') {
            eprintln!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [INPUT]\n\nFor more information, try '--help'.", arg, arg, arg);
            process::exit(2);
        }

        if input.is_none() {
            input = Some(arg.clone());
        } else {
            let mut current = input.unwrap();
            current.push(' ');
            current.push_str(arg);
            input = Some(current);
        }
        i += 1;
    }

    Config {
        fix,
        base,
        angle_unit,
        input,
    }
}

fn get_history_path() -> Option<PathBuf> {
    if let Ok(xdg) = env::var("XDG_DATA_HOME") {
        if !xdg.is_empty() {
            return Some(PathBuf::from(xdg).join("eva").join("history.txt"));
        }
    }
    if let Ok(home) = env::var("HOME") {
        if !home.is_empty() {
            return Some(PathBuf::from(home).join(".local").join("share").join("eva").join("history.txt"));
        }
    }
    None
}

fn format_number(val: f64, base: u32, fix: usize) -> String {
    if base == 10 {
        let dec_str = format!("{:.1$}", val, fix);
        let parts: Vec<&str> = dec_str.split('.').collect();
        let int_str = parts[0];
        let frac_str = if parts.len() > 1 { parts[1] } else { "" };

        let is_neg = int_str.starts_with('-');
        let digits_only = if is_neg { &int_str[1..] } else { int_str };

        let mut grouped = String::new();
        let len = digits_only.len();
        for (i, ch) in digits_only.chars().enumerate() {
            if i > 0 && (len - i) % 3 == 0 {
                grouped.push(',');
            }
            grouped.push(ch);
        }

        let prefix = if is_neg { "-" } else { "" };
        if fix > 0 {
            format!("{}{}.{}", prefix, grouped, frac_str)
        } else {
            format!("{}{}", prefix, grouped)
        }
    } else {
        let dec_str = format!("{:.1$}", val, fix);
        let v: f64 = dec_str.parse().unwrap_or(val);
        let int_part = v.abs().trunc() as u64;

        let digits_map: &[u8] = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        let mut int_digits = String::new();
        if int_part == 0 {
            int_digits.push('0');
        } else {
            let mut n = int_part;
            let mut d_vec = Vec::new();
            while n > 0 {
                d_vec.push(digits_map[(n % (base as u64)) as usize] as char);
                n /= base as u64;
            }
            d_vec.reverse();
            int_digits = d_vec.into_iter().collect();
        }

        let mut grouped = String::new();
        let len = int_digits.len();
        for (i, ch) in int_digits.chars().enumerate() {
            if i > 0 && (len - i) % 3 == 0 {
                grouped.push(',');
            }
            grouped.push(ch);
        }

        let is_neg = val < 0.0 && v.abs() > 0.0;
        let grouped_str = if is_neg {
            format!("-{}", grouped)
        } else {
            grouped
        };

        let int_formatted = if grouped_str.len() < 12 {
            let pad_len = 12 - grouped_str.len();
            let mut buf: Vec<char> = " ".repeat(pad_len).chars().chain(grouped_str.chars()).collect();
            for idx in [0, 4, 8] {
                if buf[idx] == '-' {
                    buf[idx] = ',';
                    if idx > 0 {
                        buf[idx - 1] = '-';
                    }
                } else if buf[idx] == ' ' {
                    buf[idx] = ',';
                }
            }
            buf.into_iter().collect()
        } else {
            grouped_str
        };

        let mut f = v.abs() - (int_part as f64);
        let mut frac_digits = Vec::new();
        for _ in 0..fix {
            f *= base as f64;
            let digit = f.trunc() as usize;
            let digit = digit.min((base - 1) as usize);
            frac_digits.push(digits_map[digit] as char);
            f -= digit as f64;
            if f.abs() < 1e-12 {
                break;
            }
        }

        let frac_str = if frac_digits.is_empty() {
            "0".to_string()
        } else {
            frac_digits.into_iter().collect()
        };

        format!("{}.{}", int_formatted, frac_str)
    }
}

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Num(f64),
    Pi,
    E,
    Var,
    Fn(String),
    Op(char),
}

fn tokenize(expr: &str) -> Result<Vec<Token>, String> {
    let s = expr.replace(" ", "").replace("\t", "");
    if s.is_empty() {
        return Ok(Vec::new());
    }

    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    let mut i = 0;
    let mut raw_tokens = Vec::new();

    let fn_names = [
        "acot", "acsc", "asec", "asin", "acos", "atan", "ceil", "cosh", "cot", "csc",
        "floor", "log10", "log2", "nroot", "sinh", "tanh", "abs", "cos", "log", "sec",
        "sin", "tan", "ln", "sqrt",
    ];

    while i < len {
        let ch = chars[i];

        if ch.is_ascii_digit() || (ch == '.' && i + 1 < len && chars[i + 1].is_ascii_digit()) {
            let start = i;
            let mut has_dot = ch == '.';
            i += 1;
            while i < len {
                if chars[i].is_ascii_digit() {
                    i += 1;
                } else if chars[i] == '.' && !has_dot {
                    has_dot = true;
                    i += 1;
                } else {
                    break;
                }
            }
            let num_str: String = chars[start..i].iter().collect();
            if let Ok(v) = num_str.parse::<f64>() {
                raw_tokens.push(Token::Num(v));
            } else {
                return Err("Parser Error: Too many operators, too few operands".to_string());
            }
            continue;
        }

        if chars[i..].starts_with(&['*', '*']) {
            raw_tokens.push(Token::Op('^'));
            i += 2;
            continue;
        }

        if "+-*/^(),".contains(ch) {
            raw_tokens.push(Token::Op(ch));
            i += 1;
            continue;
        }

        let mut matched_fn = None;
        for &fname in &fn_names {
            let fchars: Vec<char> = fname.chars().collect();
            if chars[i..].starts_with(&fchars) {
                matched_fn = Some(fname);
                break;
            }
        }

        if let Some(fname) = matched_fn {
            let flen = fname.len();
            if i + flen < len && chars[i + flen] == '(' {
                raw_tokens.push(Token::Fn(fname.to_string()));
                i += flen;
                continue;
            } else {
                return Err(format!("Syntax Error: Function '{}' expected parentheses", fname));
            }
        }

        if chars[i..].starts_with(&['p', 'i']) {
            raw_tokens.push(Token::Pi);
            i += 2;
            continue;
        }

        if chars[i..].starts_with(&['e']) {
            raw_tokens.push(Token::E);
            i += 1;
            continue;
        }

        if chars[i..].starts_with(&['_']) {
            raw_tokens.push(Token::Var);
            i += 1;
            continue;
        }

        if ch.is_ascii_alphabetic() || ch == '_' {
            let start = i;
            while i < len && (chars[i].is_ascii_alphanumeric() || chars[i] == '_' || chars[i] == '.') {
                i += 1;
            }
            let ident: String = chars[start..i].iter().collect();
            if i < len && chars[i] == '(' {
                return Err(format!("Syntax Error: Unknown function '{}'", ident));
            } else {
                if ident.len() > 1 && (ident.chars().any(|c| c.is_ascii_digit()) || ident.contains('_') || ident.contains('.')) {
                    let mut inv = String::new();
                    for c in ident.chars() {
                        inv.push(c);
                        if c.is_ascii_digit() || c == '_' || c == '.' {
                            break;
                        }
                    }
                    return Err(format!("Syntax Error: Unexpected character '{}'", inv));
                }
                raw_tokens.push(Token::Fn(ident));
                continue;
            }
        }

        return Err(format!("Syntax Error: Unexpected token: '{}'", ch));
    }

    let mut tokens = Vec::new();
    for j in 0..raw_tokens.len() {
        tokens.push(raw_tokens[j].clone());
        if j + 1 < raw_tokens.len() {
            let t1 = &raw_tokens[j];
            let t2 = &raw_tokens[j + 1];

            let t1_is_val = matches!(t1, Token::Num(_) | Token::Pi | Token::E | Token::Var);
            let t2_is_val_or_fn_or_paren = matches!(t2, Token::Num(_) | Token::Pi | Token::E | Token::Var | Token::Fn(_) | Token::Op('('));

            let t1_is_const = matches!(t1, Token::Pi | Token::E);
            let t2_is_num = matches!(t2, Token::Num(_));

            let t1_is_close = matches!(t1, Token::Op(')'));
            let t2_is_open = matches!(t2, Token::Op('('));

            if (t1_is_val && t2_is_val_or_fn_or_paren) || (t1_is_const && t2_is_num) || (t1_is_close && t2_is_open) {
                tokens.push(Token::Op('*'));
            }
        }
    }

    let mut open_parens = 0i32;
    for t in &tokens {
        if *t == Token::Op('(') {
            open_parens += 1;
        } else if *t == Token::Op(')') {
            open_parens -= 1;
            if open_parens < 0 {
                return Err("Syntax Error: Mismatched parentheses!".to_string());
            }
        }
    }

    while open_parens > 0 {
        tokens.push(Token::Op(')'));
        open_parens -= 1;
    }

    Ok(tokens)
}

fn eval_tokens(tokens: &[Token], angle_unit: AngleUnit, prev_ans: Option<f64>) -> Result<f64, String> {
    if tokens.is_empty() {
        return Ok(0.0);
    }
    parse_expr(tokens, angle_unit, prev_ans)
}

fn parse_expr(tokens: &[Token], angle_unit: AngleUnit, prev_ans: Option<f64>) -> Result<f64, String> {
    let mut pos = 0;
    let val = parse_binary_add_sub(tokens, &mut pos, angle_unit, prev_ans)?;
    if pos < tokens.len() {
        return Err("Parser Error: Too many operators, too few operands".to_string());
    }
    Ok(val)
}

fn parse_binary_add_sub(tokens: &[Token], pos: &mut usize, angle_unit: AngleUnit, prev_ans: Option<f64>) -> Result<f64, String> {
    let mut left = parse_binary_mul_div(tokens, pos, angle_unit, prev_ans)?;
    while *pos < tokens.len() {
        if tokens[*pos] == Token::Op('+') {
            *pos += 1;
            let right = parse_binary_mul_div(tokens, pos, angle_unit, prev_ans)?;
            left += right;
        } else if tokens[*pos] == Token::Op('-') {
            *pos += 1;
            let right = parse_binary_mul_div(tokens, pos, angle_unit, prev_ans)?;
            left -= right;
        } else {
            break;
        }
    }
    Ok(left)
}

fn parse_binary_mul_div(tokens: &[Token], pos: &mut usize, angle_unit: AngleUnit, prev_ans: Option<f64>) -> Result<f64, String> {
    let mut left = parse_power(tokens, pos, angle_unit, prev_ans)?;
    while *pos < tokens.len() {
        if tokens[*pos] == Token::Op('*') {
            *pos += 1;
            let right = parse_power(tokens, pos, angle_unit, prev_ans)?;
            left *= right;
        } else if tokens[*pos] == Token::Op('/') {
            *pos += 1;
            let right = parse_power(tokens, pos, angle_unit, prev_ans)?;
            if right == 0.0 {
                return Err("Math Error: Divide by zero error!".to_string());
            }
            left /= right;
        } else {
            break;
        }
    }
    Ok(left)
}

fn parse_power(tokens: &[Token], pos: &mut usize, angle_unit: AngleUnit, prev_ans: Option<f64>) -> Result<f64, String> {
    let left = parse_unary(tokens, pos, angle_unit, prev_ans)?;
    if *pos < tokens.len() && tokens[*pos] == Token::Op('^') {
        *pos += 1;
        let right = parse_power(tokens, pos, angle_unit, prev_ans)?;
        let res = left.powf(right);
        if res.is_nan() {
            return Err("Domain Error: Out of bounds!".to_string());
        }
        if res.is_infinite() || res.abs() > f64::MAX {
            return Err("Error: to large to process! Max value: ".to_string());
        }
        Ok(res)
    } else {
        Ok(left)
    }
}

fn parse_unary(tokens: &[Token], pos: &mut usize, angle_unit: AngleUnit, prev_ans: Option<f64>) -> Result<f64, String> {
    if *pos < tokens.len() {
        if tokens[*pos] == Token::Op('+') {
            *pos += 1;
            return parse_unary(tokens, pos, angle_unit, prev_ans);
        } else if tokens[*pos] == Token::Op('-') {
            *pos += 1;
            let val = parse_unary(tokens, pos, angle_unit, prev_ans)?;
            return Ok(-val);
        }
    }
    parse_primary(tokens, pos, angle_unit, prev_ans)
}

fn parse_primary(tokens: &[Token], pos: &mut usize, angle_unit: AngleUnit, prev_ans: Option<f64>) -> Result<f64, String> {
    if *pos >= tokens.len() {
        return Err("Parser Error: Too many operators, too few operands".to_string());
    }

    match &tokens[*pos] {
        Token::Num(v) => {
            let val = *v;
            *pos += 1;
            Ok(val)
        }
        Token::Pi => {
            *pos += 1;
            Ok(std::f64::consts::PI)
        }
        Token::E => {
            *pos += 1;
            Ok(std::f64::consts::E)
        }
        Token::Var => {
            *pos += 1;
            if let Some(v) = prev_ans {
                Ok(v)
            } else {
                Err("Syntax Error: No previous answer!".to_string())
            }
        }
        Token::Op('(') => {
            *pos += 1;
            let val = parse_binary_add_sub(tokens, pos, angle_unit, prev_ans)?;
            if *pos < tokens.len() && tokens[*pos] == Token::Op(')') {
                *pos += 1;
                Ok(val)
            } else {
                Err("Syntax Error: Mismatched parentheses!".to_string())
            }
        }
        Token::Fn(fname) => {
            let name = fname.clone();
            *pos += 1;
            if *pos >= tokens.len() || tokens[*pos] != Token::Op('(') {
                return Err(format!("Syntax Error: Function '{}' expected parentheses", name));
            }
            *pos += 1; // consume '('

            let mut paren_depth = 1;
            let mut arg_tokens = Vec::new();
            while *pos < tokens.len() {
                let t = &tokens[*pos];
                if *t == Token::Op('(') {
                    paren_depth += 1;
                } else if *t == Token::Op(')') {
                    paren_depth -= 1;
                    if paren_depth == 0 {
                        *pos += 1; // consume matching ')'
                        break;
                    }
                }
                arg_tokens.push(t.clone());
                *pos += 1;
            }

            eval_func(&name, &arg_tokens, angle_unit, prev_ans)
        }
        _ => Err("Parser Error: Too many operators, too few operands".to_string()),
    }
}

fn eval_func(name: &str, arg_tokens: &[Token], angle_unit: AngleUnit, prev_ans: Option<f64>) -> Result<f64, String> {
    let two_arg_fns = ["log", "nroot"];
    if two_arg_fns.contains(&name) {
        let mut comma_idx = None;
        let mut depth = 0;
        for (idx, t) in arg_tokens.iter().enumerate() {
            if *t == Token::Op('(') {
                depth += 1;
            } else if *t == Token::Op(')') {
                depth -= 1;
            } else if *t == Token::Op(',') && depth == 0 {
                comma_idx = Some(idx);
                break;
            }
        }

        if let Some(idx) = comma_idx {
            let arg2_first_token = arg_tokens.get(idx + 1);
            if let Some(Token::Op(c)) = arg2_first_token {
                if "+-*^/,".contains(*c) {
                    return Err("Parser Error: To few arguments for function, need 2".to_string());
                }
            }

            let arg1 = &arg_tokens[..idx];
            let arg2 = &arg_tokens[idx + 1..];

            let v1 = parse_expr(arg1, angle_unit, prev_ans)?;
            let v2 = parse_expr(arg2, angle_unit, prev_ans)?;

            if name == "log" {
                if v1 <= 0.0 || v2 <= 0.0 || v2 == 1.0 {
                    return Err("Domain Error: Out of bounds!".to_string());
                }
                Ok(v1.ln() / v2.ln())
            } else if name == "nroot" {
                if v2 == 0.0 || v1 < 0.0 {
                    return Err("Domain Error: Out of bounds!".to_string());
                }
                Ok(v1.powf(1.0 / v2))
            } else {
                Err(format!("Syntax Error: Unknown function '{}'", name))
            }
        } else {
            Err("Parser Error: To few arguments for function, need 2".to_string())
        }
    } else {
        let one_arg_fns = [
            "acot", "acsc", "asec", "asin", "acos", "atan", "ceil", "cosh", "cot", "csc",
            "floor", "log10", "log2", "sinh", "tanh", "abs", "cos", "sec", "sin", "tan",
            "ln", "sqrt",
        ];
        if !one_arg_fns.contains(&name) {
            return Err(format!("Syntax Error: Unknown function '{}'", name));
        }

        if arg_tokens.is_empty() {
            return Err("Parser Error: To few arguments for function, need 1".to_string());
        }

        let v = parse_expr(arg_tokens, angle_unit, prev_ans)?;

        let to_rad = |val: f64| -> f64 {
            match angle_unit {
                AngleUnit::Degree | AngleUnit::Gradian => val.to_radians(),
                AngleUnit::Radian => val,
            }
        };

        match name {
            "sin" => Ok(to_rad(v).sin()),
            "cos" => Ok(to_rad(v).cos()),
            "tan" => Ok(to_rad(v).tan()),
            "csc" => {
                let s = to_rad(v).sin();
                if s == 0.0 || s.abs() < 1e-15 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(1.0 / s)
                }
            }
            "sec" => {
                let c = to_rad(v).cos();
                if c == 0.0 || c.abs() < 1e-15 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(1.0 / c)
                }
            }
            "cot" => {
                let t = to_rad(v).tan();
                if t == 0.0 || t.abs() < 1e-15 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(1.0 / t)
                }
            }
            "sinh" => Ok(v.sinh()),
            "cosh" => Ok(v.cosh()),
            "tanh" => Ok(v.tanh()),
            "asin" => {
                if v < -1.0 || v > 1.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(v.asin())
                }
            }
            "acos" => {
                if v < -1.0 || v > 1.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(v.acos())
                }
            }
            "atan" => Ok(v.atan()),
            "acsc" => {
                if v == 0.0 || (1.0 / v).abs() > 1.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok((1.0 / v).asin())
                }
            }
            "asec" => {
                if v == 0.0 || (1.0 / v).abs() > 1.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok((1.0 / v).acos())
                }
            }
            "acot" => {
                if v == 0.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok((1.0 / v).atan())
                }
            }
            "ln" => {
                if v <= 0.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(v.ln())
                }
            }
            "log2" => {
                if v <= 0.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(v.log2())
                }
            }
            "log10" => {
                if v <= 0.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(v.log10())
                }
            }
            "sqrt" => {
                if v < 0.0 {
                    Err("Domain Error: Out of bounds!".to_string())
                } else {
                    Ok(v.sqrt())
                }
            }
            "ceil" => Ok(v.ceil()),
            "floor" => Ok(v.floor()),
            "abs" => Ok(v.abs()),
            _ => Err(format!("Syntax Error: Unknown function '{}'", name)),
        }
    }
}

fn eval(expr: &str, angle_unit: AngleUnit, prev_ans: Option<f64>) -> Result<f64, String> {
    let tokens = tokenize(expr)?;
    eval_tokens(&tokens, angle_unit, prev_ans)
}

fn main() {
    let config = parse_args();

    if let Some(expr) = &config.input {
        if expr.is_empty() {
            return;
        }
        match eval(expr, config.angle_unit, None) {
            Ok(v) => {
                let formatted = format_number(v, config.base, config.fix);
                println!("{}", formatted);
            }
            Err(e) => {
                eprintln!("{}", e);
                process::exit(1);
            }
        }
    } else {
        let hist_path = get_history_path();
        let mut loaded_history = false;
        if let Some(ref path) = hist_path {
            if path.exists() {
                loaded_history = true;
            }
        }

        if !loaded_history {
            println!("No previous history.");
        }

        let stdin = io::stdin();
        let mut lines = stdin.lock().lines();
        let mut prev_ans: Option<f64> = None;

        while let Some(line_res) = lines.next() {
            let line = match line_res {
                Ok(l) => l,
                Err(_) => break,
            };

            match eval(&line, config.angle_unit, prev_ans) {
                Ok(v) => {
                    prev_ans = Some(v);
                    if let Some(ref path) = hist_path {
                        if let Some(parent) = path.parent() {
                            let _ = fs::create_dir_all(parent);
                        }
                        if !path.exists() {
                            if let Ok(mut f) = File::create(path) {
                                let _ = writeln!(f, "#V2");
                            }
                        }
                        if let Ok(mut f) = OpenOptions::new().append(true).open(path) {
                            let _ = writeln!(f, "{}", line);
                        }
                    }
                    let formatted = format_number(v, config.base, config.fix);
                    println!("{}", formatted);
                }
                Err(e) => {
                    println!("{}", e);
                }
            }
        }
    }
}
